+import { createContext, useContext, useState } from 'react';
+
+const TabsContext = createContext({ activeIndex: 0, setActiveIndex: (i: number) => {} });
+
+export function TabList({ children }) {
+  return <div role="tablist">{children}</div>;
+}
+
+export function Tab({ index, children }) {
+  const { activeIndex, setActiveIndex } = useContext(TabsContext);
+  return (
+    <button role="tab" aria-selected={index === activeIndex} onClick={() => setActiveIndex(index)}>
+      {children}
+    </button>
+  );
+}
+
+export function TabPanel({ index, children }) {
+  const { activeIndex } = useContext(TabsContext);
+  if (index !== activeIndex) return null;
+  return <div role="tabpanel">{children}</div>;
+}
+
+export function Tabs({ children }) {
+  const [activeIndex, setActiveIndex] = useState(0);
+  return (
+    <TabsContext.Provider value={{ activeIndex, setActiveIndex }}>
+      {children}
+    </TabsContext.Provider>
+  );
+}
